import type { NextConfig } from "next";
import { PHASE_DEVELOPMENT_SERVER } from "next/constants";

// Static export only (deployed to Cloudflare as static assets).
// No redirects/headers/rewrites here: they live in public/_redirects and
// public/_headers, generated by scripts/ during `pnpm build`.
export default function config(phase: string): NextConfig {
  return {
    output: "export",
    trailingSlash: true,
    images: { unoptimized: true },
    reactStrictMode: true,
    poweredByHeader: false,
    // `page.dev.tsx` routes (e.g. /dev/components/) exist only under `next dev`
    // and are never part of the export.
    pageExtensions:
      phase === PHASE_DEVELOPMENT_SERVER
        ? ["dev.tsx", "tsx", "ts"]
        : ["tsx", "ts"],
    turbopack: {
      rules: {
        "*.css": {
          loaders: ["@tailwindcss/turbopack"],
          as: "*.css",
        },
      },
    },
  };
}
